// 1. Synchronous Callback (Blocking)
console.log("Start");
[1, 2, 3].forEach((num) => {
  console.log("Processing:", num); // Executes immediately
});
console.log("End of Sync");

console.log("\n---\n");

// 2. Asynchronous Callback (Non-Blocking)
console.log("1. Request User from DB");

// setTimeout simulates a 1-second database query
setTimeout(() => {
  // This arrow function is the Callback.
  // It is pushed to the side, and runs LATER.
  console.log("3. DB returned user: Alice");
}, 1000);

console.log("2. Continue doing other work while waiting...");
